import {
    useId, useRef, useState,
    type ComponentProps, type ReactNode,
} from "react";
import { Button } from "./button";
import { Combobox } from "./combobox";
import { DatePicker } from "./date-picker";
import { Input } from "./input";
import { MultiSelect } from "./multi-select";
import { NativeSelect } from "./native-select";
import { RelationPicker } from "./relation-picker";
import { cn } from "./utils";
import type { EntityReference } from "./work-management-types";

type PropertyOption = {
    value: string;
    label: string;
    disabled?: boolean;
};

type PropertyFieldBase<TValue> = {
    id: string;
    label: string;
    value: TValue;
    onSave: (value: TValue) => void | Promise<void>;
    description?: string;
    readOnly?: boolean;
    disabled?: boolean;
    required?: boolean;
    validate?: (value: TValue) => string | null;
    saveErrorMessage?: string;
};

type PropertyPersonReference = EntityReference & { kind: "person" };

type TextPropertyField = PropertyFieldBase<string | null> & {
    type: "text";
    placeholder?: string;
    maxLength?: number;
};

type PersonPropertyField = PropertyFieldBase<
    PropertyPersonReference | null
> & {
    type: "person";
    options: readonly PropertyPersonReference[];
    onQueryChange?: (query: string) => void;
    loading?: boolean;
    errorMessage?: string | null;
};

type DatePropertyField = PropertyFieldBase<string | null> & {
    type: "date";
    placeholder?: string;
};

type StatusPropertyField = PropertyFieldBase<string | null> & {
    type: "status";
    options: readonly PropertyOption[];
    placeholder?: string;
};

type MultiSelectPropertyField = PropertyFieldBase<readonly string[]> & {
    type: "multi-select";
    options: readonly PropertyOption[];
    placeholder?: string;
};

type RelationPropertyField = PropertyFieldBase<readonly EntityReference[]> & {
    type: "relation";
    options: readonly EntityReference[];
    onQueryChange?: (query: string) => void;
    loading?: boolean;
    errorMessage?: string | null;
    onOpenReference?: (reference: EntityReference) => void;
};

type PropertyPanelField =
    | TextPropertyField
    | PersonPropertyField
    | DatePropertyField
    | StatusPropertyField
    | MultiSelectPropertyField
    | RelationPropertyField;

type PropertyPanelProps = Omit<
    ComponentProps<"section">,
    "children" | "aria-label"
> & {
    fields: readonly PropertyPanelField[];
    label?: string;
    layout?: "rows" | "grid";
    emptyText?: string;
};

type PropertyControlProps<TValue> = {
    id: string;
    disabled: boolean;
    invalid: boolean;
    value: TValue;
    onChange: (value: TValue) => void;
};

type PropertyFieldEditorProps<TValue> = {
    field: PropertyFieldBase<TValue>;
    empty: (value: TValue) => boolean;
    displayValue: ReactNode;
    renderControl: (props: PropertyControlProps<TValue>) => ReactNode;
};

function PropertyFieldEditor<TValue>({
    field,
    empty,
    displayValue,
    renderControl,
}: PropertyFieldEditorProps<TValue>) {
    const controlId = useId();
    const errorId = `${controlId}-error`;
    const pendingRef = useRef(false);
    const [editing, setEditing] = useState(false);
    const [draft, setDraft] = useState(field.value);
    const [pending, setPending] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const disabled = !!field.disabled || !!field.readOnly || pending;

    async function save() {
        if (pendingRef.current || disabled) return;
        const validationError = field.required && empty(draft)
            ? "값을 입력하세요."
            : field.validate?.(draft) || null;
        if (validationError) {
            setError(validationError);
            return;
        }
        if (Object.is(draft, field.value)) {
            setError(null);
            setEditing(false);
            return;
        }

        pendingRef.current = true;
        setPending(true);
        setError(null);
        try {
            await field.onSave(draft);
            setEditing(false);
        } catch {
            setError(
                field.saveErrorMessage ??
                    "저장하지 못했습니다. 다시 시도하세요.",
            );
        } finally {
            pendingRef.current = false;
            setPending(false);
        }
    }

    function cancel() {
        if (pendingRef.current) return;
        setDraft(field.value);
        setError(null);
        setEditing(false);
    }

    return (
        <div className="min-w-0">
            {editing ? (
                <div className="grid gap-2">
                    {renderControl({
                        id: controlId,
                        disabled,
                        invalid: !!error,
                        value: draft,
                        onChange: (value) => {
                            setDraft(value);
                            setError(null);
                        },
                    })}
                    {error && (
                        <p id={errorId} role="alert"
                            className="m-0 text-xs text-danger">
                            {error}
                        </p>
                    )}
                    <div className="flex flex-wrap gap-2">
                        <Button type="button" disabled={disabled}
                            onClick={() => void save()}>
                            {pending ? "저장 중…" : "저장"}
                        </Button>
                        <Button type="button" variant="outline"
                            disabled={pending} onClick={cancel}>
                            취소
                        </Button>
                    </div>
                </div>
            ) : (
                <div className="flex min-w-0 flex-wrap items-center gap-2">
                    <div className="min-w-0 flex-1 break-words text-sm">
                        {displayValue}
                    </div>
                    {!field.readOnly && (
                        <Button type="button" variant="outline"
                            disabled={field.disabled}
                            aria-label={`${field.label} 수정`}
                            onClick={() => {
                                setDraft(field.value);
                                setError(null);
                                setEditing(true);
                            }}>
                            수정
                        </Button>
                    )}
                </div>
            )}
        </div>
    );
}

function MissingValue({ text }: { text: string }) {
    return <span className="text-muted">{text}</span>;
}

function renderPropertyField(field: PropertyPanelField) {
    switch (field.type) {
        case "text":
            return (
                <PropertyFieldEditor
                    key={field.id}
                    field={field}
                    empty={(value) => value === null || value === ""}
                    displayValue={field.value === null
                        ? <MissingValue text={field.placeholder ?? "값 없음"} />
                        : field.value}
                    renderControl={({ id, disabled, invalid, value, onChange }) => (
                        <Input id={id} aria-label={field.label}
                            aria-invalid={invalid || undefined}
                            aria-describedby={invalid ? `${id}-error` : undefined}
                            required={field.required} maxLength={field.maxLength}
                            placeholder={field.placeholder}
                            disabled={disabled} value={value ?? ""}
                            onChange={(event) => onChange(event.target.value)}
                            onKeyDown={(event) => {
                                if (event.nativeEvent.isComposing ||
                                    event.keyCode === 229) return;
                                if (event.key === "Enter") {
                                    event.preventDefault();
                                    const button = event.currentTarget
                                        .parentElement?.parentElement
                                        ?.querySelector<HTMLButtonElement>(
                                            "button:not([disabled])",
                                        );
                                    button?.click();
                                }
                            }} />
                    )}
                />
            );
        case "person": {
            const current = field.value;
            return (
                <PropertyFieldEditor
                    key={field.id}
                    field={field}
                    empty={(value) => value === null}
                    displayValue={current
                        ? <span>{current.title}</span>
                        : <MissingValue text="담당자 없음" />}
                    renderControl={({ id, disabled, invalid, value, onChange }) => {
                        const options = field.options.map((person) => ({
                            value: person.id,
                            label: person.title,
                            disabled: person.disabled,
                        }));
                        const selectedOption = value ? {
                            value: value.id,
                            label: value.title,
                            disabled: value.disabled,
                        } : undefined;
                    const selected = value;
                        return (
                            <div className="grid gap-2">
                                <Combobox
                                    id={id}
                                    aria-label={field.label}
                                    placeholder="사람 검색"
                                    options={options}
                                    value={selected?.id ?? null}
                                    selectedOption={selectedOption}
                                    filterOptions={!field.onQueryChange}
                                    loading={field.loading}
                                    errorMessage={field.errorMessage}
                                    disabled={disabled}
                                    onQueryChange={field.onQueryChange}
                                    onValueChange={(personId) => {
                                        if (personId === null) return;
                                        const person = field.options.find(
                                            (option) => option.id === personId,
                                        );
                                        if (person) onChange(person);
                                    }}
                                    aria-invalid={invalid || undefined}
                                />
                                {value && (
                                    <Button type="button" variant="outline"
                                        disabled={disabled}
                                        aria-label={`${field.label} 지우기`}
                                        onClick={() => onChange(null)}>
                                        선택 지우기
                                    </Button>
                                )}
                            </div>
                        );
                    }}
                />
            );
        }
        case "date":
            return (
                <PropertyFieldEditor
                    key={field.id}
                    field={field}
                    empty={(value) => value === null}
                    displayValue={field.value === null
                        ? <MissingValue text={field.placeholder ?? "날짜 없음"} />
                        : <time dateTime={field.value}>{field.value}</time>}
                    renderControl={({ id, disabled, invalid, value, onChange }) => (
                        <DatePicker id={id} aria-label={field.label}
                            aria-invalid={invalid || undefined}
                            value={value} onValueChange={onChange}
                            placeholder={field.placeholder ?? "날짜 선택"}
                            required={field.required} disabled={disabled} />
                    )}
                />
            );
        case "status": {
            const selectedLabel = field.value === null || field.value === ""
                ? null
                : field.options.find((option) =>
                    option.value === field.value,
                )?.label ?? `알 수 없는 값 (${field.value})`;
            const hasCurrentUnknown = !!field.value &&
                !field.options.some((option) =>
                    option.value === field.value,
                );
            return (
                <PropertyFieldEditor
                    key={field.id}
                    field={field}
                    empty={(value) => value === null || value === ""}
                    displayValue={selectedLabel ??
                        <MissingValue text={field.placeholder ?? "값 없음"} />}
                    renderControl={({ id, disabled, invalid, value, onChange }) => (
                        <NativeSelect id={id} aria-label={field.label}
                            aria-invalid={invalid || undefined}
                            disabled={disabled} required={field.required}
                            value={value ?? ""}
                            onChange={(event) => onChange(
                                event.target.value || null,
                            )}>
                            <option value="">
                                {field.placeholder ?? "값 선택"}
                            </option>
                            {hasCurrentUnknown && (
                                <option value={field.value ?? ""} disabled>
                                    알 수 없는 값 ({field.value})
                                </option>
                            )}
                            {field.options.map((option) => (
                                <option key={option.value}
                                    value={option.value}
                                    disabled={option.disabled}>
                                    {option.label}
                                </option>
                            ))}
                        </NativeSelect>
                    )}
                />
            );
        }
        case "multi-select": {
            const optionLabels = new Map(field.options.map((option) => [
                option.value,
                option.label,
            ]));
            const selectedLabels = field.value.map((value) =>
                optionLabels.get(value) ?? `알 수 없는 값 (${value})`,
            );
            return (
                <PropertyFieldEditor
                    key={field.id}
                    field={field}
                    empty={(value) => value.length === 0}
                    displayValue={selectedLabels.length > 0
                        ? <span>{selectedLabels.join(", ")}</span>
                        : <MissingValue text={field.placeholder ?? "값 없음"} />}
                    renderControl={({ id, disabled, invalid, value, onChange }) => {
                        const known = new Set(field.options.map((option) =>
                            option.value,
                        ));
                        const options = [
                            ...field.options,
                            ...value.filter((item) => !known.has(item)).map(
                                (item) => ({
                                    value: item,
                                    label: `알 수 없는 값 (${item})`,
                                    disabled: true,
                                }),
                            ),
                        ];
                        return (
                            <MultiSelect id={id}
                                aria-label={field.label}
                                aria-invalid={invalid || undefined}
                                options={options}
                                value={[...value]}
                                onValueChange={onChange}
                                placeholder={field.placeholder ?? "값 선택"}
                                disabled={disabled}
                            />
                        );
                    }}
                />
            );
        }
        case "relation": {
            const value = field.value;
            return (
                <PropertyFieldEditor
                    key={field.id}
                    field={field}
                    empty={(items) => items.length === 0}
                    displayValue={value.length ? (
                        <span>{value.map((item) => item.title).join(", ")}</span>
                    ) : (
                        <MissingValue text="연결된 항목이 없습니다." />
                    )}
                    renderControl={({ disabled, value: draft, onChange }) => (
                        <RelationPicker
                            label={field.label}
                            value={[...draft]}
                            options={field.options}
                            onValueChange={onChange}
                            onQueryChange={field.onQueryChange}
                            onOpenReference={field.onOpenReference}
                            loading={field.loading}
                            errorMessage={field.errorMessage}
                            disabled={disabled}
                        />
                    )}
                />
            );
        }
    }
}

function PropertyPanel({
    fields,
    label = "속성",
    layout = "rows",
    emptyText = "표시할 속성이 없습니다.",
    className,
    ...props
}: PropertyPanelProps) {
    if (!label.trim()) throw new Error("PropertyPanel requires a label.");
    if (layout !== "rows" && layout !== "grid") {
        throw new RangeError("PropertyPanel layout is not supported.");
    }
    if (!Array.isArray(fields)) {
        throw new TypeError("PropertyPanel fields must be an array.");
    }
    const ids = new Set<string>();
    for (const field of fields) {
        if (!field.id.trim() || !field.label.trim()) {
            throw new Error("PropertyPanel fields need IDs and labels.");
        }
        if (ids.has(field.id)) {
            throw new Error(`PropertyPanel field ID is duplicated: ${field.id}`);
        }
        ids.add(field.id);
    }

    return (
        <section {...props} aria-label={label}
            className={cn("@container min-w-0", className)}>
            <h2 className="m-0 mb-[var(--space-3)] text-base font-semibold">
                {label}
            </h2>
            {fields.length === 0 ? (
                <p role="status" className="m-0 text-sm text-muted">
                    {emptyText}
                </p>
            ) : (
                <dl className={cn(
                    "m-0 grid gap-x-[var(--space-4)] gap-y-[var(--space-4)]",
                    layout === "grid" && "@md:grid-cols-2",
                )}>
                    {fields.map((field) => (
                        <div key={field.id} className={cn(
                            "grid min-w-0 gap-2",
                            layout === "rows" &&
                                "@md:grid-cols-[minmax(8rem,0.7fr)_minmax(0,1.5fr)] " +
                                "@md:items-start",
                        )}>
                            <dt className="min-w-0 text-sm font-medium text-muted">
                                <span>{field.label}</span>
                                {field.description && (
                                    <span className="mt-1 block text-xs font-normal">
                                        {field.description}
                                    </span>
                                )}
                            </dt>
                            <dd className="m-0 min-w-0">
                                {renderPropertyField(field)}
                            </dd>
                        </div>
                    ))}
                </dl>
            )}
        </section>
    );
}

export { PropertyPanel };
export type {
    DatePropertyField,
    MultiSelectPropertyField,
    PersonPropertyField,
    PropertyFieldBase,
    PropertyOption,
    PropertyPanelField,
    PropertyPanelProps,
    PropertyPersonReference,
    RelationPropertyField,
    StatusPropertyField,
    TextPropertyField,
};
